DELIMITER $$
DROP PROCEDURE IF EXISTS iw_dict_v2_apply$$
CREATE PROCEDURE iw_dict_v2_apply()
BEGIN
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 START TRANSACTION;
DROP TEMPORARY TABLE IF EXISTS dict_v2_issues;
CREATE TEMPORARY TABLE dict_v2_issues(kind VARCHAR(20),entity_id INT UNSIGNED,reason VARCHAR(255));
DROP TEMPORARY TABLE IF EXISTS dict_v2_categories;
CREATE TEMPORARY TABLE dict_v2_categories AS
 SELECT user_id,dict_code,COUNT(*) candidate_count,MIN(id) source_id,MIN(dict_name) source_name
 FROM base_dict WHERE dict_type=4002 AND scope_type=0 AND family_group_id=0 GROUP BY user_id,dict_code;
-- MIN values are ONLY consumed when candidate_count=1; no ambiguous source is chosen.

INSERT INTO dict_v2_issues SELECT 'record',id,'invalid bill category' FROM bookkeeping_records WHERE dictionary_snapshot_status=0 AND record_category NOT IN (1,2);
INSERT INTO dict_v2_issues SELECT 'action',id,'invalid quick action category' FROM bookkeeping_actions WHERE record_category NOT IN (1,2);
INSERT INTO dict_v2_issues
 SELECT 'record',r.id,'category source missing/ambiguous' FROM bookkeeping_records r
 LEFT JOIN dict_v2_categories c ON c.user_id=r.user_id AND c.dict_code=r.record_type
 WHERE r.dictionary_snapshot_status=0 AND NOT
 (COALESCE(c.candidate_count,0)=1 OR (COALESCE(r.record_type,0)=0 AND COALESCE(c.candidate_count,0)=0));
INSERT INTO dict_v2_issues
 SELECT DISTINCT 'record',r.id,'tag source missing/wrong owner/wrong type' FROM bookkeeping_records r
 JOIN base_dict_business_relation rel ON rel.business_type=4001 AND rel.business_id=r.id
 LEFT JOIN base_dict d ON d.id=rel.dict_id WHERE r.dictionary_snapshot_status=0 AND
 (d.id IS NULL OR d.dict_type<>IF(r.record_category=1,4001,4011) OR d.scope_type<>0 OR d.family_group_id<>0 OR d.user_id<>r.user_id);
INSERT INTO dict_v2_issues
 SELECT DISTINCT 'record',r.id,'existing partial snapshot conflicts with migration baseline' FROM bookkeeping_records r
 JOIN bookkeeping_record_tag_snapshot s ON s.record_id=r.id
 LEFT JOIN base_dict_business_relation rel ON rel.business_type=4001 AND rel.business_id=r.id AND rel.dict_id=s.source_dict_id
 LEFT JOIN base_dict d ON d.id=s.source_dict_id WHERE r.dictionary_snapshot_status=0 AND
 (rel.id IS NULL OR d.id IS NULL OR s.dict_type<>d.dict_type OR BINARY s.tag_name<>BINARY d.dict_name);
INSERT INTO dict_v2_issues
 SELECT 'record',r.id,'existing partial category snapshot requires reviewed repair' FROM bookkeeping_records r
 WHERE r.dictionary_snapshot_status=0 AND (r.record_type_id IS NOT NULL OR r.record_type_name IS NOT NULL);
DROP TEMPORARY TABLE IF EXISTS dict_v2_records;
CREATE TEMPORARY TABLE dict_v2_records AS
 SELECT r.id,c.source_id,c.source_name FROM bookkeeping_records r
 LEFT JOIN dict_v2_categories c ON c.user_id=r.user_id AND c.dict_code=r.record_type AND COALESCE(c.candidate_count,0)=1
 WHERE r.dictionary_snapshot_status=0 AND NOT EXISTS(SELECT 1 FROM dict_v2_issues e WHERE e.kind='record' AND e.entity_id=r.id);
INSERT INTO bookkeeping_record_tag_snapshot(record_id,dict_type,source_dict_id,tag_name)
 SELECT DISTINCT r.id,d.dict_type,d.id,d.dict_name FROM dict_v2_records r
 JOIN base_dict_business_relation rel ON rel.business_type=4001 AND rel.business_id=r.id
 JOIN base_dict d ON d.id=rel.dict_id
 WHERE NOT EXISTS(SELECT 1 FROM bookkeeping_record_tag_snapshot s WHERE s.record_id=r.id AND s.dict_type=d.dict_type AND s.source_dict_id=d.id);
-- Mark complete only after the category AND every tag succeeded in this transaction.
UPDATE bookkeeping_records r JOIN dict_v2_records c ON c.id=r.id
 SET r.record_type_id=c.source_id,r.record_type_name=c.source_name,r.dictionary_snapshot_status=1
 WHERE r.dictionary_snapshot_status=0;

DROP TEMPORARY TABLE IF EXISTS dict_v2_budgets;
CREATE TEMPORARY TABLE dict_v2_budgets AS
 SELECT b.id,b.user_id,b.budget_type,b.budget_month,b.budget_year,b.deleted,c.candidate_count,
 CASE WHEN b.budget_type IN (1,2) THEN NULL ELSE c.source_id END source_id,
 CASE WHEN b.budget_type IN (1,2) THEN NULL ELSE c.source_name END source_name
 FROM bookkeeping_budget b LEFT JOIN dict_v2_categories c ON c.user_id=b.user_id AND c.dict_code=b.record_type AND COALESCE(c.candidate_count,0)=1;
INSERT INTO dict_v2_issues SELECT 'budget',id,'category source missing/ambiguous'
 FROM dict_v2_budgets WHERE budget_type IN (11,21) AND COALESCE(candidate_count,0)<>1;
DROP TEMPORARY TABLE IF EXISTS dict_v2_budget_duplicates;
CREATE TEMPORARY TABLE dict_v2_budget_duplicates AS
 SELECT user_id,budget_type,budget_month,budget_year,BINARY source_name name_key,COUNT(*) n
 FROM dict_v2_budgets WHERE deleted=0 GROUP BY user_id,budget_type,budget_month,budget_year,BINARY source_name HAVING COUNT(*)>1;
INSERT INTO dict_v2_issues SELECT 'budget',b.id,'duplicate same-name budget; do not combine amounts' FROM dict_v2_budgets b
 JOIN dict_v2_budget_duplicates x ON x.user_id=b.user_id AND x.budget_type=b.budget_type
 AND x.budget_month<=>b.budget_month AND x.budget_year<=>b.budget_year AND x.name_key<=>BINARY b.source_name WHERE b.deleted=0;
UPDATE bookkeeping_budget b JOIN dict_v2_budgets m ON m.id=b.id
 SET b.record_type_id=m.source_id,b.record_type_name=m.source_name
 WHERE b.record_type_id IS NULL AND b.record_type_name IS NULL AND b.budget_type IN (11,21)
 AND NOT EXISTS(SELECT 1 FROM dict_v2_issues e WHERE e.kind='budget' AND e.entity_id=b.id);

-- Quick actions are future configurations. Disabled/deleted references are reported, never substituted.
INSERT INTO dict_v2_issues SELECT 'action',a.id,'category source missing/ambiguous'
 FROM bookkeeping_actions a LEFT JOIN dict_v2_categories c ON c.user_id=a.user_id AND c.dict_code=a.record_type
 WHERE a.record_type_id IS NULL AND NOT(COALESCE(c.candidate_count,0)=1 OR (a.record_type=0 AND COALESCE(c.candidate_count,0)=0));
INSERT INTO dict_v2_issues SELECT 'action',id,'invalid tag ID list'
 FROM bookkeeping_actions WHERE NOT JSON_VALID(CONCAT('[',record_tags,']'));
INSERT INTO dict_v2_issues SELECT DISTINCT 'action',a.id,'tag source missing/wrong owner/wrong type'
 FROM bookkeeping_actions a JOIN JSON_TABLE(IF(JSON_VALID(CONCAT('[',a.record_tags,']')),CONCAT('[',a.record_tags,']'),'[]'),'$[*]'
 COLUMNS(ordinal_num FOR ORDINALITY, source_id BIGINT PATH '$' NULL ON ERROR)) j LEFT JOIN base_dict d ON d.id=j.source_id
 WHERE COALESCE(JSON_TYPE(JSON_EXTRACT(CONCAT('[',a.record_tags,']'),CONCAT('$[',j.ordinal_num-1,']'))),'NULL') NOT IN ('INTEGER','UNSIGNED INTEGER') OR j.source_id<=0 OR d.deleted<>0 OR d.dict_status<>1 OR d.id IS NULL OR d.user_id<>a.user_id OR d.scope_type<>0 OR d.family_group_id<>0 OR d.dict_type<>IF(a.record_category=1,4001,4011);
INSERT INTO dict_v2_issues SELECT 'action',a.id,'future category is disabled/deleted; reconfigure'
 FROM bookkeeping_actions a JOIN dict_v2_categories c ON c.user_id=a.user_id AND c.dict_code=a.record_type AND COALESCE(c.candidate_count,0)=1
 JOIN base_dict d ON d.id=c.source_id WHERE a.deleted=0 AND (d.deleted<>0 OR d.dict_status<>1);
UPDATE bookkeeping_actions a JOIN dict_v2_categories c ON c.user_id=a.user_id AND c.dict_code=a.record_type AND COALESCE(c.candidate_count,0)=1
 SET a.record_type_id=c.source_id WHERE a.record_type_id IS NULL
 AND NOT EXISTS(SELECT 1 FROM dict_v2_issues e WHERE e.kind='action' AND e.entity_id=a.id);

-- JSON_SET preserves unknown/amount/source/statistics fields. Known schema1 ONLY, never downgrade schema2+.
DROP TEMPORARY TABLE IF EXISTS dict_v2_templates;
CREATE TEMPORARY TABLE dict_v2_templates(kind VARCHAR(20),id INT UNSIGNED,user_id INT UNSIGNED,body JSON,
 record_category INT,old_code INT,source_id INT UNSIGNED,source_name VARCHAR(32) CHARACTER SET utf8mb4,
 upgraded JSON,PRIMARY KEY(kind,id));
INSERT INTO dict_v2_templates(kind,id,user_id,body,record_category,old_code)
 SELECT 'plan',id,user_id,bookkeeping_template,
 CASE WHEN JSON_TYPE(JSON_EXTRACT(bookkeeping_template,'$.recordCategory')) IN ('INTEGER','UNSIGNED INTEGER') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(bookkeeping_template,'$.recordCategory')) AS UNSIGNED) ELSE NULL END,
 CASE WHEN JSON_TYPE(JSON_EXTRACT(bookkeeping_template,'$.recordType')) IN ('INTEGER','UNSIGNED INTEGER') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(bookkeeping_template,'$.recordType')) AS UNSIGNED) ELSE NULL END
 FROM points_task_plan WHERE JSON_TYPE(JSON_EXTRACT(bookkeeping_template,'$.schemaVersion')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(bookkeeping_template,'$.schemaVersion')=1;
INSERT INTO dict_v2_templates(kind,id,user_id,body,record_category,old_code)
 SELECT 'task',id,user_id,template_snapshot,
 CASE WHEN JSON_TYPE(JSON_EXTRACT(template_snapshot,'$.recordCategory')) IN ('INTEGER','UNSIGNED INTEGER') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(template_snapshot,'$.recordCategory')) AS UNSIGNED) ELSE NULL END,
 CASE WHEN JSON_TYPE(JSON_EXTRACT(template_snapshot,'$.recordType')) IN ('INTEGER','UNSIGNED INTEGER') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(template_snapshot,'$.recordType')) AS UNSIGNED) ELSE NULL END
 FROM points_task_bookkeeping WHERE JSON_TYPE(JSON_EXTRACT(template_snapshot,'$.schemaVersion')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(template_snapshot,'$.schemaVersion')=1;
INSERT INTO dict_v2_issues SELECT 'plan',id,'unknown template schema; re-save template'
 FROM points_task_plan WHERE bookkeeping_template IS NOT NULL
 AND (COALESCE(JSON_TYPE(JSON_EXTRACT(bookkeeping_template,'$.schemaVersion')),'NULL') NOT IN ('INTEGER','UNSIGNED INTEGER') OR JSON_EXTRACT(bookkeeping_template,'$.schemaVersion') NOT IN (1,2));
INSERT INTO dict_v2_issues SELECT 'task',id,'unknown template schema; re-save template'
 FROM points_task_bookkeeping WHERE COALESCE(JSON_TYPE(JSON_EXTRACT(template_snapshot,'$.schemaVersion')),'NULL') NOT IN ('INTEGER','UNSIGNED INTEGER') OR JSON_EXTRACT(template_snapshot,'$.schemaVersion') NOT IN (1,2);
INSERT INTO dict_v2_issues SELECT t.kind,t.id,'template category missing/ambiguous/invalid'
 FROM dict_v2_templates t LEFT JOIN dict_v2_categories c ON c.user_id=t.user_id AND c.dict_code=t.old_code
 WHERE t.record_category NOT IN (1,2) OR t.record_category IS NULL
 OR COALESCE(JSON_TYPE(JSON_EXTRACT(t.body,'$.recordCategory')),'NULL') NOT IN ('INTEGER','UNSIGNED INTEGER')
 OR COALESCE(JSON_TYPE(JSON_EXTRACT(t.body,'$.recordType')),'NULL') NOT IN ('INTEGER','UNSIGNED INTEGER','NULL')
 OR NOT(COALESCE(c.candidate_count,0)=1 OR (COALESCE(t.old_code,0)=0 AND COALESCE(c.candidate_count,0)=0));
INSERT INTO dict_v2_issues SELECT t.kind,t.id,'future category is disabled/deleted; re-save template'
 FROM dict_v2_templates t JOIN dict_v2_categories c ON c.user_id=t.user_id AND c.dict_code=t.old_code AND COALESCE(c.candidate_count,0)=1
 JOIN base_dict d ON d.id=c.source_id WHERE d.deleted<>0 OR d.dict_status<>1;
INSERT INTO dict_v2_issues SELECT kind,id,'template tags must be array of source IDs' FROM dict_v2_templates
 WHERE COALESCE(JSON_TYPE(JSON_EXTRACT(body,'$.recordTags')),'NULL') NOT IN ('ARRAY','NULL');
INSERT INTO dict_v2_issues SELECT DISTINCT t.kind,t.id,'template tag source missing/wrong owner/wrong type'
 FROM dict_v2_templates t JOIN JSON_TABLE(IF(JSON_TYPE(JSON_EXTRACT(t.body,'$.recordTags'))='ARRAY',JSON_EXTRACT(t.body,'$.recordTags'),JSON_ARRAY()),'$[*]'
 COLUMNS(ordinal_num FOR ORDINALITY, source_id BIGINT PATH '$' NULL ON ERROR)) j LEFT JOIN base_dict d ON d.id=j.source_id
 WHERE COALESCE(JSON_TYPE(JSON_EXTRACT(t.body,CONCAT('$.recordTags[',j.ordinal_num-1,']'))),'NULL') NOT IN ('INTEGER','UNSIGNED INTEGER') OR j.source_id<=0 OR d.deleted<>0 OR d.dict_status<>1 OR d.id IS NULL OR d.user_id<>t.user_id OR d.scope_type<>0 OR d.family_group_id<>0 OR d.dict_type<>IF(t.record_category=1,4001,4011);
UPDATE dict_v2_templates t LEFT JOIN dict_v2_categories c ON c.user_id=t.user_id AND c.dict_code=t.old_code AND COALESCE(c.candidate_count,0)=1
 SET t.source_id=c.source_id,t.source_name=c.source_name;
UPDATE dict_v2_templates t SET upgraded=JSON_SET(JSON_REMOVE(t.body,'$.recordType'),
 '$.schemaVersion',2,'$.recordTypeId',t.source_id,'$.recordTypeName',t.source_name,
 '$.recordTagSnapshots',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',d.id,'type',d.dict_type,'name',d.dict_name))
 FROM JSON_TABLE(IF(JSON_TYPE(JSON_EXTRACT(t.body,'$.recordTags'))='ARRAY',JSON_EXTRACT(t.body,'$.recordTags'),JSON_ARRAY()),'$[*]'
 COLUMNS(ordinal_num FOR ORDINALITY, source_id BIGINT PATH '$' NULL ON ERROR)) j JOIN base_dict d ON d.id=j.source_id),JSON_ARRAY()))
 WHERE NOT EXISTS(SELECT 1 FROM dict_v2_issues e WHERE e.kind=t.kind AND e.entity_id=t.id);
UPDATE points_task_plan p JOIN dict_v2_templates t ON t.kind='plan' AND t.id=p.id
 SET p.bookkeeping_template=t.upgraded WHERE t.upgraded IS NOT NULL AND JSON_EXTRACT(p.bookkeeping_template,'$.schemaVersion')=1;
UPDATE points_task_bookkeeping p JOIN dict_v2_templates t ON t.kind='task' AND t.id=p.id
 SET p.template_snapshot=t.upgraded WHERE t.upgraded IS NOT NULL AND JSON_EXTRACT(p.template_snapshot,'$.schemaVersion')=1;

 IF EXISTS(SELECT 1 FROM dict_v2_issues) THEN
  SELECT * FROM dict_v2_issues ORDER BY kind,entity_id,reason;
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: backfill issues; this run is rolled back';
 END IF;
DROP TEMPORARY TABLE IF EXISTS dict_v2_families;
CREATE TEMPORARY TABLE dict_v2_families(family_group_id INT UNSIGNED PRIMARY KEY);

INSERT INTO dict_v2_families SELECT g.id FROM auth_family_group g
 LEFT JOIN bookkeeping_family_dict_state s ON s.family_group_id=g.id
 WHERE g.deleted=0 AND g.status=1 AND s.family_group_id IS NULL;
INSERT INTO base_dict(parent_id,dict_type,dict_code,dict_name,dict_status,sort,user_id,scope_type,family_group_id,revision)
 SELECT 0,4002,0,d.dict_name,d.dict_status,d.sort,0,1,g.family_group_id,0
 FROM dict_v2_families g JOIN base_dict d ON d.user_id=0 AND d.scope_type=0 AND d.family_group_id=0
 AND d.dict_type=4002 AND d.deleted=0 AND d.dict_status=1;
-- A conflict rolls back BOTH copies and markers. Do not use INSERT IGNORE.
INSERT INTO bookkeeping_family_dict_state(family_group_id) SELECT family_group_id FROM dict_v2_families;

 DROP TEMPORARY TABLE IF EXISTS dict_v2_checks;
 CREATE TEMPORARY TABLE dict_v2_checks AS
SELECT 'bill_category' check_name, COUNT(*) exception_count FROM (
SELECT id,'invalid bill category' issue FROM bookkeeping_records WHERE record_category NOT IN (1,2)
) exceptions
UNION ALL
SELECT 'unresolved_bills' check_name, COUNT(*) exception_count FROM (
SELECT id,user_id,record_type,'unresolved bill snapshot' issue FROM bookkeeping_records WHERE dictionary_snapshot_status<>1
) exceptions
UNION ALL
SELECT 'category_snapshot_pair' check_name, COUNT(*) exception_count FROM (
SELECT id,'inconsistent category snapshot' issue FROM bookkeeping_records
 WHERE (record_type_id IS NULL)<>(record_type_name IS NULL)
) exceptions
UNION ALL
SELECT 'tag_snapshot' check_name, COUNT(*) exception_count FROM (
SELECT s.id,s.record_id,'invalid tag snapshot/type' issue FROM bookkeeping_record_tag_snapshot s
 LEFT JOIN bookkeeping_records r ON r.id=s.record_id WHERE r.id IS NULL OR s.dict_type<>IF(r.record_category=1,4001,4011)
 OR CHAR_LENGTH(s.tag_name) NOT BETWEEN 1 AND 32 OR BINARY s.tag_name<>BINARY REGEXP_REPLACE(s.tag_name,@dict_trim_pattern,'')
) exceptions
UNION ALL
SELECT 'duplicate_dict_name' check_name, COUNT(*) exception_count FROM (
SELECT scope_type,family_group_id,user_id,dict_type,HEX(dict_name) name_bytes,COUNT(*) duplicate_count FROM base_dict
 WHERE deleted=0 AND dict_type IN (4001,4002,4011)
 GROUP BY scope_type,family_group_id,user_id,dict_type,HEX(dict_name) HAVING COUNT(*)>1
) exceptions
UNION ALL
SELECT 'dict_name_owner' check_name, COUNT(*) exception_count FROM (
SELECT id,'noncanonical name/ownership' issue FROM base_dict WHERE dict_type IN (4001,4002,4011) AND
 (BINARY dict_name<>BINARY REGEXP_REPLACE(dict_name,@dict_trim_pattern,'') OR CHAR_LENGTH(dict_name) NOT BETWEEN 1 AND 32
 OR scope_type NOT IN (0,1) OR (scope_type=0 AND family_group_id<>0) OR (scope_type=1 AND (family_group_id=0 OR user_id<>0)))
) exceptions
UNION ALL
SELECT 'duplicate_successor' check_name, COUNT(*) exception_count FROM (
SELECT previous_id,COUNT(*) successors FROM base_dict WHERE previous_id IS NOT NULL GROUP BY previous_id HAVING COUNT(*)>1
) exceptions
UNION ALL
SELECT 'rename_lineage' check_name, COUNT(*) exception_count FROM (
SELECT n.id,'invalid rename lineage' issue FROM base_dict n LEFT JOIN base_dict o ON o.id=n.previous_id
 WHERE n.previous_id IS NOT NULL AND (o.id IS NULL OR o.deleted<>1 OR o.dict_type<>n.dict_type OR o.user_id<>n.user_id
 OR o.scope_type<>n.scope_type OR o.family_group_id<>n.family_group_id OR n.id<=o.id)
) exceptions
UNION ALL
SELECT 'budget_category' check_name, COUNT(*) exception_count FROM (
SELECT id,'missing category budget snapshot' issue FROM bookkeeping_budget
 WHERE budget_type IN (11,21) AND (record_type_id IS NULL OR record_type_name IS NULL)
) exceptions
UNION ALL
SELECT 'total_budget_category' check_name, COUNT(*) exception_count FROM (
SELECT id,'total budget must not have category' issue FROM bookkeeping_budget
 WHERE budget_type IN (1,2) AND (record_type_id IS NOT NULL OR record_type_name IS NOT NULL)
) exceptions
UNION ALL
SELECT 'duplicate_budget' check_name, COUNT(*) exception_count FROM (
SELECT user_id,budget_type,budget_month,budget_year,HEX(record_type_name) name_bytes,COUNT(*) duplicate_count
 FROM bookkeeping_budget WHERE deleted=0 GROUP BY user_id,budget_type,budget_month,budget_year,HEX(record_type_name) HAVING COUNT(*)>1
) exceptions
UNION ALL
SELECT 'action_category_missing' check_name, COUNT(*) exception_count FROM (
SELECT id,'missing quick action category reference' issue FROM bookkeeping_actions WHERE record_type<>0 AND record_type_id IS NULL
) exceptions
UNION ALL
SELECT 'action_tags' check_name, COUNT(*) exception_count FROM (
SELECT DISTINCT a.id,'invalid quick action tag reference' issue
 FROM bookkeeping_actions a JOIN JSON_TABLE(IF(JSON_VALID(CONCAT('[',a.record_tags,']')),CONCAT('[',a.record_tags,']'),'[]'),'$[*]'
 COLUMNS(ordinal_num FOR ORDINALITY, source_id BIGINT PATH '$' NULL ON ERROR)) j LEFT JOIN base_dict d ON d.id=j.source_id
 WHERE COALESCE(JSON_TYPE(JSON_EXTRACT(CONCAT('[',a.record_tags,']'),CONCAT('$[',j.ordinal_num-1,']'))),'NULL') NOT IN ('INTEGER','UNSIGNED INTEGER') OR j.source_id<=0 OR d.deleted<>0 OR d.dict_status<>1 OR d.id IS NULL OR d.user_id<>a.user_id OR d.scope_type<>0 OR d.family_group_id<>0 OR d.dict_type<>IF(a.record_category=1,4001,4011)
) exceptions
UNION ALL
SELECT 'action_category' check_name, COUNT(*) exception_count FROM (
SELECT a.id,'invalid quick action category' issue FROM bookkeeping_actions a LEFT JOIN base_dict d ON d.id=a.record_type_id
 WHERE a.deleted=0 AND a.record_type_id IS NOT NULL AND (d.id IS NULL OR d.user_id<>a.user_id OR d.scope_type<>0 OR d.family_group_id<>0 OR d.dict_type<>4002 OR d.deleted<>0 OR d.dict_status<>1)
) exceptions
UNION ALL
SELECT 'action_tag_list' check_name, COUNT(*) exception_count FROM (
SELECT id,'invalid quick action tag list' issue FROM bookkeeping_actions WHERE NOT JSON_VALID(CONCAT('[',record_tags,']'))
) exceptions
UNION ALL
SELECT 'plan_schema' check_name, COUNT(*) exception_count FROM (
SELECT 'plan' kind,id,'template requires re-save/upgrade' issue FROM points_task_plan WHERE bookkeeping_template IS NOT NULL
 AND (COALESCE(JSON_TYPE(JSON_EXTRACT(bookkeeping_template,'$.schemaVersion')),'NULL') NOT IN ('INTEGER','UNSIGNED INTEGER') OR JSON_EXTRACT(bookkeeping_template,'$.schemaVersion')<>2)
) exceptions
UNION ALL
SELECT 'task_schema' check_name, COUNT(*) exception_count FROM (
SELECT 'task' kind,id,'template requires re-save/upgrade' issue FROM points_task_bookkeeping
 WHERE COALESCE(JSON_TYPE(JSON_EXTRACT(template_snapshot,'$.schemaVersion')),'NULL') NOT IN ('INTEGER','UNSIGNED INTEGER') OR JSON_EXTRACT(template_snapshot,'$.schemaVersion')<>2
) exceptions
UNION ALL
SELECT 'template_category' check_name, COUNT(*) exception_count FROM (
WITH templates AS (
 SELECT 'plan' kind,id,user_id,bookkeeping_template body FROM points_task_plan WHERE bookkeeping_template IS NOT NULL
 UNION ALL SELECT 'task',id,user_id,template_snapshot FROM points_task_bookkeeping
)
SELECT t.kind,t.id,'invalid schema2 category reference' issue FROM templates t
 LEFT JOIN base_dict d ON d.id=CASE WHEN JSON_TYPE(JSON_EXTRACT(t.body,'$.recordTypeId')) IN ('INTEGER','UNSIGNED INTEGER') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(t.body,'$.recordTypeId')) AS UNSIGNED) ELSE NULL END
 WHERE JSON_EXTRACT(t.body,'$.schemaVersion')=2 AND
 (COALESCE(JSON_TYPE(JSON_EXTRACT(t.body,'$.recordCategory')),'NULL') NOT IN ('INTEGER','UNSIGNED INTEGER')
 OR JSON_EXTRACT(t.body,'$.recordCategory') NOT IN (1,2)
 OR COALESCE(JSON_TYPE(JSON_EXTRACT(t.body,'$.recordTags')),'NULL') NOT IN ('ARRAY','NULL')
 OR JSON_TYPE(JSON_EXTRACT(t.body,'$.recordTypeId')) NOT IN ('INTEGER','UNSIGNED INTEGER','NULL') OR
 (JSON_TYPE(JSON_EXTRACT(t.body,'$.recordTypeId')) IN ('INTEGER','UNSIGNED INTEGER') AND
 (d.id IS NULL OR d.dict_type<>4002 OR d.user_id<>t.user_id OR d.scope_type<>0 OR d.family_group_id<>0 OR d.deleted<>0 OR d.dict_status<>1)))
) exceptions
UNION ALL
SELECT 'template_tags' check_name, COUNT(*) exception_count FROM (
WITH templates AS (
 SELECT 'plan' kind,id,user_id,bookkeeping_template body FROM points_task_plan WHERE bookkeeping_template IS NOT NULL
 UNION ALL SELECT 'task',id,user_id,template_snapshot FROM points_task_bookkeeping
)
SELECT DISTINCT t.kind,t.id,'invalid schema2 tag reference' issue FROM templates t
 JOIN JSON_TABLE(IF(JSON_TYPE(JSON_EXTRACT(t.body,'$.recordTags'))='ARRAY',JSON_EXTRACT(t.body,'$.recordTags'),JSON_ARRAY()),'$[*]'
 COLUMNS(ordinal_num FOR ORDINALITY,source_id BIGINT PATH '$' NULL ON ERROR)) j LEFT JOIN base_dict d ON d.id=j.source_id
 WHERE JSON_EXTRACT(t.body,'$.schemaVersion')=2 AND
 (COALESCE(JSON_TYPE(JSON_EXTRACT(t.body,CONCAT('$.recordTags[',j.ordinal_num-1,']'))),'NULL') NOT IN ('INTEGER','UNSIGNED INTEGER')
 OR j.source_id<=0 OR d.id IS NULL OR d.dict_type<>IF(JSON_EXTRACT(t.body,'$.recordCategory')=1,4001,4011)
 OR d.user_id<>t.user_id OR d.scope_type<>0 OR d.family_group_id<>0 OR d.deleted<>0 OR d.dict_status<>1)
) exceptions
UNION ALL
SELECT 'family_marker' check_name, COUNT(*) exception_count FROM (
SELECT g.id,'active family without initialization marker' issue FROM auth_family_group g
 LEFT JOIN bookkeeping_family_dict_state s ON s.family_group_id=g.id WHERE g.deleted=0 AND g.status=1 AND s.family_group_id IS NULL
) exceptions
UNION ALL
SELECT 'baseline_changed' check_name, COUNT(*) exception_count FROM (
SELECT b.metric,b.row_count expected_rows,v.row_count actual_rows,b.amount expected_amount,v.amount actual_amount,
 b.fingerprint expected_fingerprint,v.fingerprint actual_fingerprint,
 (b.row_count=v.row_count AND (b.amount<=>v.amount) AND b.fingerprint=v.fingerprint) unchanged
 FROM bookkeeping_dictionary_migration_baseline b JOIN (
 SELECT 'records' metric,COUNT(*) row_count,COALESCE(SUM(amount),0) amount,
 BIT_XOR(CRC32(CONCAT_WS('|',id,user_id,COALESCE(expense_user_id,'NULL'),record_category,amount,record_date,group_id,share_state,deleted))) fingerprint FROM bookkeeping_records
 UNION ALL SELECT 'wallet',COUNT(*),COALESCE(SUM(wallet_balance),0),BIT_XOR(CRC32(CONCAT_WS('|',id,user_id,wallet_balance,wallet_assets,deleted))) FROM bookkeeping_wallet
 UNION ALL SELECT 'relations',COUNT(*),NULL,BIT_XOR(CRC32(CONCAT_WS('|',id,business_type,business_id,dict_id))) FROM base_dict_business_relation
 UNION ALL SELECT 'other_dict',COUNT(*),NULL,BIT_XOR(CRC32(CONCAT_WS('|',id,user_id,dict_type,dict_code,dict_name,dict_status,sort,deleted))) FROM base_dict WHERE dict_type NOT IN (4001,4002,4011)
 ) v ON b.metric=v.metric
) b WHERE unchanged<>1
UNION ALL
SELECT 'baseline_missing' check_name, 4-COUNT(*) exception_count FROM bookkeeping_dictionary_migration_baseline WHERE metric IN ('records','wallet','relations','other_dict')
UNION ALL
SELECT 'schema_columns' check_name, COUNT(*) exception_count FROM (
SELECT 'base_dict' tbl,'scope_type' col,'tinyint' dtype,'NO' nullable,NULL len,'0' defval
UNION ALL
SELECT 'base_dict' tbl,'family_group_id' col,'int' dtype,'NO' nullable,NULL len,'0' defval
UNION ALL
SELECT 'base_dict' tbl,'previous_id' col,'int' dtype,'YES' nullable,NULL len,NULL defval
UNION ALL
SELECT 'base_dict' tbl,'revision' col,'int' dtype,'NO' nullable,NULL len,'0' defval
UNION ALL
SELECT 'base_dict' tbl,'active_name_key' col,'varbinary' dtype,'YES' nullable,'128' len,NULL defval
UNION ALL
SELECT 'bookkeeping_records' tbl,'record_type_id' col,'int' dtype,'YES' nullable,NULL len,NULL defval
UNION ALL
SELECT 'bookkeeping_records' tbl,'record_type_name' col,'varchar' dtype,'YES' nullable,'32' len,NULL defval
UNION ALL
SELECT 'bookkeeping_records' tbl,'dictionary_snapshot_status' col,'tinyint' dtype,'NO' nullable,NULL len,'0' defval
UNION ALL
SELECT 'bookkeeping_budget' tbl,'record_type_id' col,'int' dtype,'YES' nullable,NULL len,NULL defval
UNION ALL
SELECT 'bookkeeping_budget' tbl,'record_type_name' col,'varchar' dtype,'YES' nullable,'32' len,NULL defval
UNION ALL
SELECT 'bookkeeping_actions' tbl,'record_type_id' col,'int' dtype,'YES' nullable,NULL len,NULL defval
UNION ALL
SELECT 'bookkeeping_record_tag_snapshot' tbl,'id' col,'int' dtype,'NO' nullable,NULL len,NULL defval
UNION ALL
SELECT 'bookkeeping_record_tag_snapshot' tbl,'record_id' col,'int' dtype,'NO' nullable,NULL len,NULL defval
UNION ALL
SELECT 'bookkeeping_record_tag_snapshot' tbl,'dict_type' col,'smallint' dtype,'NO' nullable,NULL len,NULL defval
UNION ALL
SELECT 'bookkeeping_record_tag_snapshot' tbl,'source_dict_id' col,'int' dtype,'NO' nullable,NULL len,NULL defval
UNION ALL
SELECT 'bookkeeping_record_tag_snapshot' tbl,'tag_name' col,'varchar' dtype,'NO' nullable,'32' len,NULL defval
UNION ALL
SELECT 'bookkeeping_family_dict_state' tbl,'family_group_id' col,'int' dtype,'NO' nullable,NULL len,NULL defval
UNION ALL
SELECT 'bookkeeping_family_dict_state' tbl,'initialized_at' col,'datetime' dtype,'NO' nullable,NULL len,'CURRENT_TIMESTAMP' defval
) e LEFT JOIN information_schema.columns c ON c.table_schema=DATABASE() AND c.table_name=e.tbl AND c.column_name=e.col
WHERE c.column_name IS NULL OR c.data_type<>e.dtype OR c.is_nullable<>e.nullable
OR (e.len IS NOT NULL AND c.character_maximum_length<>CAST(e.len AS UNSIGNED))
OR (e.dtype IN ('int','smallint') AND c.column_type NOT LIKE '%unsigned%')
OR (e.dtype='varchar' AND (c.character_set_name<>'utf8mb4' OR c.collation_name<>'utf8mb4_bin'))
OR (e.defval IS NOT NULL AND NOT(UPPER(c.column_default)<=>e.defval))
OR (e.col='active_name_key' AND (c.extra<>'STORED GENERATED' OR c.generation_expression NOT LIKE '%dict_type%'))
UNION ALL
SELECT 'schema_indexes' check_name,COUNT(*) exception_count FROM (
SELECT 'base_dict' tbl,'uk_bookkeeping_dict_name' idx,0 non_unique,'scope_type,family_group_id,user_id,dict_type,active_name_key' cols
UNION ALL
SELECT 'base_dict' tbl,'uk_dict_previous' idx,0 non_unique,'previous_id' cols
UNION ALL
SELECT 'base_dict' tbl,'idx_bookkeeping_scope' idx,1 non_unique,'scope_type,family_group_id,user_id,dict_type,deleted' cols
UNION ALL
SELECT 'bookkeeping_record_tag_snapshot' tbl,'PRIMARY' idx,0 non_unique,'id' cols
UNION ALL
SELECT 'bookkeeping_record_tag_snapshot' tbl,'uk_record_tag_source' idx,0 non_unique,'record_id,dict_type,source_dict_id' cols
UNION ALL
SELECT 'bookkeeping_record_tag_snapshot' tbl,'idx_record_tag_type' idx,1 non_unique,'record_id,dict_type' cols
UNION ALL
SELECT 'bookkeeping_family_dict_state' tbl,'PRIMARY' idx,0 non_unique,'family_group_id' cols
) e LEFT JOIN (
 SELECT table_name,index_name,non_unique,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols,
 SUM(sub_part IS NOT NULL) prefix_columns,MIN(is_visible) is_visible
 FROM information_schema.statistics WHERE table_schema=DATABASE()
 GROUP BY table_name,index_name,non_unique
) s ON s.table_name=e.tbl AND s.index_name=e.idx
WHERE s.index_name IS NULL OR s.non_unique<>e.non_unique OR s.cols<>e.cols OR s.prefix_columns<>0 OR s.is_visible<>'YES';

 IF EXISTS(SELECT 1 FROM dict_v2_checks WHERE exception_count<>0) THEN
  SELECT * FROM dict_v2_checks WHERE exception_count<>0;
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STOP: verification failed before commit; this run is rolled back';
 END IF;
 COMMIT;
 SELECT 'MIGRATION_PASS' result,
  (SELECT COUNT(*) FROM dict_v2_records) records_migrated_this_run,
  (SELECT COUNT(*) FROM dict_v2_templates WHERE upgraded IS NOT NULL) templates_upgraded_this_run,
  (SELECT COUNT(*) FROM dict_v2_families) families_initialized_this_run;
END$$
DELIMITER ;
CALL iw_dict_v2_apply();
DROP PROCEDURE iw_dict_v2_apply;
